parameters.jsCode:
// Determine application type and route accordingly
const applyUrl = $input.item.json.apply_url;
const contactEmail = $input.item.json.contact_email;

let applicationType = 'Web Form';
let nextNode = 'browser-automation';

if (contactEmail && contactEmail.includes('@')) {
  applicationType = 'Direct Email';
  nextNode = 'email-application';
} else if (applyUrl.includes('linkedin.com')) {
  applicationType = 'LinkedIn Easy Apply';
  nextNode = 'manual-review'; // LinkedIn requires manual handling
}

return {
  json: {
    ...$input.item.json,
    application_type: applicationType,
    next_step: nextNode
  }
};

