messages.user:
Analyze this job application page HTML and identify all form fields:

Page Title: {{ $json.title }}
URL: {{ $json.url }}
HTML (first 5000 chars): {{ $json.html.substring(0, 5000) }}

parameters.body:
={
  "code": `
    async function({ page, data, formFields }) {
      await page.goto(data.apply_url, { waitUntil: 'networkidle2' });

      // Fill form fields using LLM-provided selectors
      for (const field of formFields.form_fields) {
        try {
          const element = await page.$(field.selector);
          if (!element) continue;

          const fieldType = field.field_type;

          if (fieldType === 'name') {
            await element.type(data.personal_info.full_name);
          } else if (fieldType === 'email') {
            await element.type(data.personal_info.email);
          } else if (fieldType === 'phone') {
            await element.type(data.personal_info.phone);
          } else if (fieldType === 'resume') {
            const fileInput = await page.$(field.selector);
            await fileInput.uploadFile('/workspace/resumes/resume.pdf');
          } else if (fieldType === 'cover_letter') {
            await element.type(data.cover_letter);
          }
        } catch (err) {
          console.log('Field error:', field.selector, err.message);
        }
      }

      // Click submit button
      const submitBtn = await page.$(formFields.submit_button_selector);
      if (submitBtn) {
        await Promise.all([
          page.waitForNavigation({ waitUntil: 'networkidle2', timeout: 10000 }),
          submitBtn.click()
        ]);

        // Check for success message
        const content = await page.content();
        const success = content.toLowerCase().includes('thank you') || 
                       content.toLowerCase().includes('application submitted') ||
                       content.toLowerCase().includes('confirmation');

        return {
          success: success,
          final_url: page.url(),
          message: success ? 'Application submitted successfully' : 'Submitted but no confirmation found'
        };
      } else {
        return {
          success: false,
          error: 'Submit button not found'
        };
      }
    }
  `,
  "data": {{ JSON.stringify($json) }},
  "formFields": {{ JSON.stringify($json.llm_analysis) }}
}
